pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address logger, bool status) public {
        vm.assume(logger != address(this));

        // owner (test contract, deployer) approves itself first
        c.setApprovedLogger(address(this), true);
        assertTrue(c.approvedToLog(address(this)));

        // owner approves an arbitrary logger address with arbitrary status
        c.setApprovedLogger(logger, status);

        // GENERAL RULE: after setApprovedLogger(logger, status), the flag at
        // `logger` equals `status` AND the owner's own flag is untouched.
        assertTrue(
            c.approvedToLog(logger) == status &&
            c.approvedToLog(address(this))
        );
    }
}

