pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant OWNER = address(0); // _contractOwner is never assigned, so it defaults to address(0)

    function setUp() public { c = new C(); }

    function testFuzz_property(address logger) public {
        // Owner is address(0); the logger must be a key distinct from the owner's
        vm.assume(logger != OWNER);

        // Owner approves the fuzzed logger
        vm.prank(OWNER);
        c.setApprovedLogger(logger, true);

        // General rule: the exact fuzzed key the owner approved is now an approved
        // logger, and the owner's own key is NOT approved. The mutant writes the
        // owner's key instead, so approvedLoggers(logger) stays false for every
        // logger != owner while approvedToLog(owner) wrongly becomes true.
        assertTrue(c.approvedToLog(logger) && !c.approvedToLog(OWNER));
    }
}

