    C c;
    address constant OWNER = address(0); // _contractOwner is never set, so it is address(0)

    function setUp() public { c = new C(); }

    function testFuzz_property(address logger, bytes32 digest, bytes32 r, bytes32 s) public {
        vm.assume(logger != address(0));
        // owner approves the fuzzed logger
        vm.prank(OWNER);
        c.setApprovedLogger(logger, true);
        assertTrue(c.approvedToLog(logger), "approval should persist");

        // approved logger calls logGotRedemptionSignature
        vm.prank(logger);
        bool ok = c.logGotRedemptionSignature(digest, r, s);

        // general rule: an approved logger always gets true back
        assertTrue(ok, "approved logger must receive true");
    }
